 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The 2-barrier remains fixed; each 4 falls one cell unless blocked.
    # A 4 resting immediately above the barrier traces two upward diagonals.
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    for r, c in fours:
        out[r][c] = 0
    for r, c in fours:
        nr = r + 1
        if nr < h and grid[nr][c] != 2:
            out[nr][c] = 4
            landing_r = nr
        else:
            out[r][c] = 4
            landing_r = r
        if landing_r + 1 < h and grid[landing_r + 1][c] == 2:
            for dc in (-1, 1):
                rr, cc = landing_r, c
                while 0 <= rr - 1 < h and 0 <= cc + dc < w:
                    rr -= 1
                    cc += dc
                    if out[rr][cc] != 2:
                        out[rr][cc] = 4
    return out
